// Code generated by `task gen` (go run ./internal/app/gen/capabilities in apps/desktop). DO NOT EDIT.
//
// The capabilities of the host, declared by the Go core (apps/desktop/internal/app/capabilities.go,
// ADR-0045 §1). mountWorkbench reads the running core's own answer (SettingsAPI.Capabilities) before
// the first render; CORE_CAPABILITIES are the values per kind of host until then (and in unit tests).
// To add a capability, declare it in capabilities.go, gate the Host method or binding it needs, and
// run `task gen` (docs/desktop-web-sync.md, "Capability").

/** What the host offers: `true` = the UI shows the control. */
export interface CoreCapabilities {
  /**
   * Open a folder of the computer as a vault, pick a folder to import. The browser has cloud vaults
   * only (Host.OpenDirectory fails there).
   */
  localFolders: boolean;
  /**
   * Automatic updates of the application. The Web UI is served by the cloud and is always current
   * (every UpdaterAPI method fails in the browser).
   */
  updater: boolean;
  /**
   * Warn when the disk is not encrypted (a private vault's keys may end up on it). The browser
   * cannot tell: VaultCryptoAPI.DiskEncryption always answers "unknown" there.
   */
  diskEncryptionCheck: boolean;
  /**
   * The window itself (full screen through the OS, the system browser for external links). In the
   * browser Host.ShowWindow does nothing and links open in a new tab.
   */
  nativeWindow: boolean;
  /**
   * Deleted files can go to the system trash; the browser always uses the vault's `.trash/`
   * (systemTrash fails there).
   */
  osTrash: boolean;
  /**
   * Several vaults over time in one window: recent vaults, switching from the vault menu. The
   * browser opens one vault per page, chosen in the console.
   */
  multiVault: boolean;
  /**
   * A local vault can be disconnected from the cloud and kept as a plain folder. In the browser the
   * copy belongs to the cloud vault: it is removed from the browser instead.
   */
  unlinkVault: boolean;
  /**
   * The application owns the cloud session (sign-in through the system browser, sign-out, choice of
   * the server). In the browser the session is the page's OIDC one, managed by the console: the
   * core takes its tokens from the page (SessionHost) and has no sign-in of its own.
   */
  ownsSession: boolean;
  /**
   * A copy that leaves the cloud can stay on this device as a folder of its own: the desktop keeps
   * the mount of a revoked share as an ordinary vault. The browser has no place where such a folder
   * could be opened again (SharingAPI.RemoveMount refuses keepCopy there): it offers to download
   * the copy as a ZIP instead.
   */
  detachedCopies: boolean;
  /**
   * A file the application cannot show (an archive, an office document) opens with the application
   * of the system, and any file can be shown in the file manager (ADR-0047). The browser offers to
   * download it instead (Host.OpenPath and Host.RevealPath fail there).
   */
  openWithSystemApp: boolean;
  /**
   * The writing assistant of the editor (ADR-0050): the model is reached from the Go core, which
   * only the desktop links (AIAPI refuses every call in the browser, whose Content-Security-Policy
   * allows no third party). Even on the desktop it is inactive: it also needs the `ai` flag of the
   * profile, a build that enables it, a vault that is not private and a configured provider
   * (AIAPI.Status).
   */
  aiAssistant: boolean;
}

/** The kinds of host. */
export type HostKind = 'desktop' | 'web';

/** What each kind of host offers, as its core declares it. */
export const CORE_CAPABILITIES: Readonly<Record<HostKind, Readonly<CoreCapabilities>>> = {
  desktop: {
    localFolders: true,
    updater: true,
    diskEncryptionCheck: true,
    nativeWindow: true,
    osTrash: true,
    multiVault: true,
    unlinkVault: true,
    ownsSession: true,
    detachedCopies: true,
    openWithSystemApp: true,
    aiAssistant: true,
  },
  web: {
    localFolders: false,
    updater: false,
    diskEncryptionCheck: false,
    nativeWindow: false,
    osTrash: false,
    multiVault: false,
    unlinkVault: false,
    ownsSession: false,
    detachedCopies: false,
    openWithSystemApp: false,
    aiAssistant: false,
  },
};
